import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Founding Beta","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Founding Beta | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/product/founding-beta"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Founding Beta | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/product/founding-beta"}]]},"headers":[],"relativePath":"product/founding-beta.md","filePath":"product/founding-beta.md","lastUpdated":1787351200000}'),o={name:"product/founding-beta.md"};function s(r,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="founding-beta" tabindex="-1">Founding Beta <a class="header-anchor" href="#founding-beta" aria-label="Permalink to &quot;Founding Beta&quot;">​</a></h1><p>EloSync is in <strong>Founding Beta</strong> — a pre-launch phase focused on recruiting real businesses to run real workflows, report product problems, and shape the roadmap.</p><blockquote><p><strong>Product principle</strong></p><p>We&#39;re building EloSync <strong>with</strong> real businesses, not only <strong>for</strong> them.</p></blockquote><p>Related: <a href="/getting-started/product-roadmap">Product Roadmap</a> · <a href="/developer-guide/central-feedback-system">Central Feedback System</a> (architecture) · <a href="/deployment/founding-beta-invite-production-readiness">Production readiness</a> · Marketing site campaign: <code>https://elosync.com/beta/</code></p><hr><h2 id="_1-beta-objectives" tabindex="-1">1. Beta objectives <a class="header-anchor" href="#_1-beta-objectives" aria-label="Permalink to &quot;1. Beta objectives&quot;">​</a></h2><ol><li>Put EloSync in front of businesses that will use it with <strong>real operational work</strong>.</li><li>Collect <strong>actionable</strong> feedback: bugs, UX friction, missing features, performance, and integration needs.</li><li>Validate module workflows end-to-end across CRM → Sales → Billing → Finance → HR → Inventory.</li><li>Turn feedback into triage decisions in the <strong>Central Application</strong>, then into roadmap and releases.</li><li>Avoid a conventional paid launch posture (no “buy now” / aggressive trial sell) until the product-learning loop is healthy.</li></ol><hr><h2 id="_2-target-beta-users" tabindex="-1">2. Target beta users <a class="header-anchor" href="#_2-target-beta-users" aria-label="Permalink to &quot;2. Target beta users&quot;">​</a></h2><p>Ideal participants:</p><ul><li>Small and mid-size businesses running operations across <strong>multiple tools today</strong></li><li>Teams willing to use EloSync for at least one real workflow (not only a clickthrough demo)</li><li>Operators who can articulate what EloSync should <strong>replace</strong></li><li>People with authority (or sponsorship) to try connected CRM / billing / people / operations workflows</li></ul><p>Not a priority for founding beta:</p><ul><li>Agencies shopping for white-label resale without hands-on testing</li><li>Pure “feature tourism” without any real workflow commitment</li><li>Competitors running extractive evaluation only</li></ul><hr><h2 id="_3-beta-access-model" tabindex="-1">3. Beta access model <a class="header-anchor" href="#_3-beta-access-model" aria-label="Permalink to &quot;3. Beta access model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Policy</th></tr></thead><tbody><tr><td>Cost</td><td><strong>Free during Founding Beta</strong> — no credit card required</td></tr><tr><td>Capacity</td><td>Limited cohort (quality of feedback over volume)</td></tr><tr><td>Entitlements</td><td>Participants receive workspace access to available Marketplace modules per current catalog rules</td></tr><tr><td>Pricing narrative</td><td>Catalog pricing (included / free opt-in / paid add-ons such as Branded) may be published for transparency but is <strong>not</strong> the conversion goal during beta</td></tr><tr><td>Intake</td><td>Public application via marketing site <code>/beta/</code> → Central public API (see feedback / beta intake implementation notes)</td></tr><tr><td>Activation</td><td>Central reviews the application, chooses <strong>Accept &amp; send invite</strong>, and the applicant registers with the tokenized link</td></tr><tr><td>Expired links</td><td>An accepted applicant can request a replacement invite from the marketing beta page; the response does not reveal whether an eligible application exists</td></tr></tbody></table><h3 id="invite-led-access-flow" tabindex="-1">Invite-led access flow <a class="header-anchor" href="#invite-led-access-flow" aria-label="Permalink to &quot;Invite-led access flow&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Apply on /beta/</span></span>
<span class="line"><span>→ Central reviews the application</span></span>
<span class="line"><span>→ Accept &amp; send invite</span></span>
<span class="line"><span>→ Applicant opens the tokenized registration link</span></span>
<span class="line"><span>→ Workspace registration consumes the invite</span></span></code></pre></div><p>Public self-service registration stays off during Founding Beta (<code>registration_enabled = false</code>). A valid <code>invite_token</code> is the only bypass: it must belong to an accepted, unactivated application that already received an invite, must not be expired, and registration must use the application&#39;s email address.</p><p>If the link expires, the applicant uses <strong>Resend your workspace invite</strong> on <code>/beta/</code>. Resending only works after Central has already issued an invite (status <strong>Accepted</strong> alone is not enough). It rotates the token and expiry, invalidating the previous link.</p><p>When public registration is later enabled, an invalid/expired/activated <code>invite_token</code> falls back to normal workspace registration; an email mismatch on a still-valid invite still fails validation.</p><p><code>founding_beta_enabled</code> and <code>founding_beta_apply_url</code> (absolute URL) control the registration-closed call to action. Invite lifetime is <strong>1–90 days</strong> (<code>founding_beta_invite_ttl_days</code>). Keep the beta flag on and point the URL to the public application page during the cohort. Later, operators can turn the beta CTA off or change its destination without enabling open registration.</p><p>Go-live: <a href="/deployment/founding-beta-invite-production-readiness">Founding Beta invite production readiness</a>.</p><hr><h2 id="_4-feedback-philosophy" tabindex="-1">4. Feedback philosophy <a class="header-anchor" href="#_4-feedback-philosophy" aria-label="Permalink to &quot;4. Feedback philosophy&quot;">​</a></h2><ul><li>Prefer <strong>specific, reproducible reports</strong> over vague sentiment.</li><li>Prefer feedback from <strong>real workflows</strong> over sandbox-only clicks.</li><li>Separate <strong>bugs</strong> (broken) from <strong>UX</strong> (confusing) from <strong>features</strong> (missing).</li><li>Internal triage priority and internal notes stay on the Central team; tenants see public status/responses only.</li><li>Roadmap influence is earned by frequency, severity, and multi-tenant signal — not by the loudest single request.</li></ul><p>Continuous loop:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tenant uses EloSync</span></span>
<span class="line"><span>→ experiences friction</span></span>
<span class="line"><span>→ submits feedback</span></span>
<span class="line"><span>→ Central team triages</span></span>
<span class="line"><span>→ roadmap / fix decision</span></span>
<span class="line"><span>→ release</span></span>
<span class="line"><span>→ tenant benefits</span></span>
<span class="line"><span>→ loop continues</span></span></code></pre></div><hr><h2 id="_5-bug-reporting-process" tabindex="-1">5. Bug reporting process <a class="header-anchor" href="#_5-bug-reporting-process" aria-label="Permalink to &quot;5. Bug reporting process&quot;">​</a></h2><p><strong>During / after in-app feedback ships</strong> (see <a href="/developer-guide/central-feedback-system">Central Feedback System</a>):</p><ol><li>Tenant user opens <strong>Give Feedback</strong> in the tenant app.</li><li>Chooses type <strong>Bug</strong>, describes expected vs actual, attaches screenshot when useful.</li><li>System captures workspace, user, route/module, and environment context automatically.</li><li>Central team triages (reproduce → status → priority).</li><li>Public responses / status updates are visible to the submitting tenant when appropriate.</li></ol><p>Until the in-app channel is live, founding beta participants may use the agreed operator channel called out in their onboarding mail.</p><hr><h2 id="_6-feature-request-process" tabindex="-1">6. Feature request process <a class="header-anchor" href="#_6-feature-request-process" aria-label="Permalink to &quot;6. Feature request process&quot;">​</a></h2><ol><li>Submit as type <strong>Feature Request</strong> with the problem to solve (not only a solution sketch).</li><li>Include which modules / tools the request would replace or connect.</li><li>Central associates requests with modules; roadmap linkage can be added when issue/roadmap integration exists.</li><li>Participants receive acknowledgement via public response where the Central team chooses to reply.</li></ol><hr><h2 id="_7-ux-feedback-process" tabindex="-1">7. UX feedback process <a class="header-anchor" href="#_7-ux-feedback-process" aria-label="Permalink to &quot;7. UX feedback process&quot;">​</a></h2><ol><li>Submit as type <strong>UX / Usability</strong>.</li><li>Capture what the user tried to do, where they got stuck, and what they expected.</li><li>Screenshots and route context are especially valuable.</li><li>UX themes that recur across tenants inform product polish before paid launch.</li></ol><hr><h2 id="_8-product-roadmap-relationship" tabindex="-1">8. Product roadmap relationship <a class="header-anchor" href="#_8-product-roadmap-relationship" aria-label="Permalink to &quot;8. Product roadmap relationship&quot;">​</a></h2><ul><li>The <a href="/getting-started/product-roadmap">Product Roadmap</a> remains the long-term <strong>Business Operating System</strong> direction (Phases 1–8 shipped; Future Expansion is a tiered candidate backlog).</li><li>Founding Beta does <strong>not</strong> rewrite platform freeze or module architecture standards.</li><li>Feedback informs <strong>priority within</strong> Near-term / Parked / Out-of-scope tiers — it does not invent parallel product foundations or resurrect demoted verticals (manufacturing, POS, e-commerce) without clear demand.</li><li>Marketing positioning during beta emphasizes <strong>Business Operating System</strong> (connected modular operations), not “another CRM” and not unfinished SAP.</li></ul><hr><h2 id="_9-beta-tester-expectations" tabindex="-1">9. Beta tester expectations <a class="header-anchor" href="#_9-beta-tester-expectations" aria-label="Permalink to &quot;9. Beta tester expectations&quot;">​</a></h2><p>Participants should:</p><ul><li>Use EloSync with at least one real workflow</li><li>Report bugs and confusing UX promptly</li><li>Be honest about what they would replace</li><li>Accept that beta software will change and may break</li><li>Not redistribute credentials or scrape the product</li></ul><p>EloSync will:</p><ul><li>Provide free beta access</li><li>Review feedback in Central</li><li>Communicate material status changes when useful</li><li>Credit founding participants with priority consideration on requests that fit the product vision</li></ul><hr><h2 id="_10-transition-from-beta-to-public-launch" tabindex="-1">10. Transition from beta to public launch <a class="header-anchor" href="#_10-transition-from-beta-to-public-launch" aria-label="Permalink to &quot;10. Transition from beta to public launch&quot;">​</a></h2><p>Planned transition criteria (product judgment, not a hard checklist):</p><ol><li>Core CRM → Sales → Billing workflows are stable for beta cohorts.</li><li>Feedback volume of <strong>Critical / High</strong> bugs is trending down.</li><li>Central feedback triage process is operational.</li><li>Pricing / billing surfaces are ready without contradicting beta promises.</li><li>Marketing CTAs can shift from Founding Beta recruitment to self-serve / commercial conversion.</li></ol><p>When launch begins:</p><ul><li>Document what happens to beta workspaces and any founding pricing commitments</li><li>Freeze contradictory “free forever everything” marketing claims</li><li>Keep the feedback loop as a permanent product channel (not a temporary beta-only gadget)</li></ul><hr><h2 id="status-of-related-systems" tabindex="-1">Status of related systems <a class="header-anchor" href="#status-of-related-systems" aria-label="Permalink to &quot;Status of related systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Status</th></tr></thead><tbody><tr><td>Marketing Founding Beta pages</td><td>Shipped (<code>/</code>, <code>/beta/</code>, <code>/pricing/</code>, module pages)</td></tr><tr><td>Public beta application + invite APIs</td><td>Shipped (apply, invite preview, self-resend, token registration)</td></tr><tr><td>Tenant in-app feedback submission</td><td>Shipped (user menu + command palette → Give Feedback)</td></tr><tr><td>Central feedback + beta applications UI</td><td>Shipped (<strong>Platform → Feedback</strong>, <strong>Platform → Beta Applications</strong>)</td></tr><tr><td>This product page</td><td>Living — update when access model or expectations change</td></tr></tbody></table>`,57)])])}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
